Frontend (JavaScript):

Create a JavaScript file named `prime_number.js` for interactivity.

```javascript
// prime_number.js
function generatePrimeNumbers() {
    var num = document.getElementById("num").value;
    var primes = getPrimes(num);
    document.getElementById("result").innerHTML = "Prime numbers up to " + num + ": " + primes.join(", ");
}

function getPrimes(num) {
    var sieve = [], i, j, primes = [];
    for (i = 2; i <= num; ++i) {
        if (!sieve[i]) {
            primes.push(i);
            for (j = i << 1; j <= num; j += i) {
                sieve[j] = true;
            }
        }
    }
    return primes;
}
```

Backend (Python):

Create a Python file named `prime_number.py` for backend logic.

```python
# prime_number.py
def get_primes(n):
    sieve = [0] * (n+1)
    for x in range(1, int(n**0.5) + 1):
        if sieve[x]: continue
        for u in range(x*2, n+1, x): sieve[u] = 1
    return [x for x in range(2, n+1) if not sieve[x]]

# Testing
if __name__ == "__main__":
    print(get_primes(10))  # Output: [2, 3, 5, 7]
```

